using System;
using System.Collections.Generic;
using AdKit;
using JellyAd;
using UnityEngine;

namespace RescueRun
{
    /// <summary>
    /// Real CC0 3D models downloaded from poly.pizza (SwatSoldier /m/Btfn3G5Xv4, AssaultRifle /m/XGeBGFQxYg,
    /// HeavyRifle /m/Bgvuu4CUMV, Zombie /m/ftpTNkeqGWc), pre-normalized and baked for 100% Playworks WebGL compatibility.
    /// Raw .obj files are also stored under Assets/Resources/Models/.
    /// </summary>
    public static class PolyPizzaModels
    {
        static readonly Dictionary<string, Mesh> _meshes = new Dictionary<string, Mesh>();
        static bool _loaded;

        public static Mesh Get(string name)
        {
            if (!_loaded) LoadAll();
            _meshes.TryGetValue(name, out var m);
            return m;
        }

        public static GameObject Part(string meshName, Transform parent, Vector3 localPos, Vector3 localScale, Color color)
        {
            var m = Get(meshName);
            if (!m) return Prims.Make(PrimitiveType.Cube, parent, localPos, localScale, color);
            var go = new GameObject(meshName);
            go.transform.SetParent(parent, false);
            go.transform.localPosition = localPos;
            go.transform.localScale = localScale;
            var mf = go.AddComponent<MeshFilter>();
            mf.sharedMesh = m;
            var mr = go.AddComponent<MeshRenderer>();
            if (Res.PrimMat) mr.sharedMaterial = Res.PrimMat;
            Prims.SetColor(mr, color);
            return go;
        }

        static void LoadAll()
        {
            _loaded = true;
            byte[] data = Convert.FromBase64String(BankBase64);
            int p = 0;
            int meshCount = ReadU16(data, ref p);
            for (int m = 0; m < meshCount; m++)
            {
                int nLen = data[p++];
                string name = System.Text.Encoding.UTF8.GetString(data, p, nLen);
                p += nLen;
                int vCount = ReadU16(data, ref p);
                int tCount = ReadU16(data, ref p);
                var verts = new Vector3[vCount];
                var norms = new Vector3[vCount];
                for (int i = 0; i < vCount; i++)
                {
                    short qx = ReadI16(data, ref p);
                    short qy = ReadI16(data, ref p);
                    short qz = ReadI16(data, ref p);
                    sbyte nx = (sbyte)data[p++];
                    sbyte ny = (sbyte)data[p++];
                    sbyte nz = (sbyte)data[p++];
                    verts[i] = new Vector3(qx / 4000f, qy / 4000f, qz / 4000f);
                    norms[i] = new Vector3(nx / 127f, ny / 127f, nz / 127f).normalized;
                }
                var tris = new int[tCount * 3];
                for (int i = 0; i < tCount * 3; i++)
                {
                    tris[i] = ReadU16(data, ref p);
                }
                var mesh = new Mesh { name = name };
                mesh.vertices = verts;
                mesh.normals = norms;
                mesh.triangles = tris;
                mesh.RecalculateBounds();
                _meshes[name] = mesh;
            }
        }

        static ushort ReadU16(byte[] d, ref int p)
        {
            ushort v = (ushort)(d[p] | (d[p + 1] << 8));
            p += 2;
            return v;
        }

        static short ReadI16(byte[] d, ref int p)
        {
            short v = (short)(d[p] | (d[p + 1] << 8));
            p += 2;
            return v;
        }

